cat > build.py <<'EOF'
import json, math, itertools
names = ["Depot","A","B","C","D","E","F"]
pts = [(0,0),(2,9),(7,3),(12,8),(5,12),(10,1),(1,5)]
d = [[math.dist(p,q) for q in pts] for p in pts]
cust = list(range(1,7)); n = len(cust)          # depot fixed at start/end
idx = lambda c,t: (c-1)*n + t                   # var = customer c at step t
P = round(n*max(map(max,d)),2)
Q = {}
def add(i,j,v):
    k=(min(i,j),max(i,j)); Q[k]=Q.get(k,0)+v
lin=[0.0]*(n*n)
# one-hot rows (each customer once) and columns (each step one customer)
groups=[[idx(c,t) for t in range(n)] for c in cust]+[[idx(c,t) for c in cust] for t in range(n)]
for g in groups:
    for i in g: lin[i]-=P
    for i,j in itertools.combinations(g,2): add(i,j,2*P)
for c in cust:
    lin[idx(c,0)]+=d[0][c]; lin[idx(c,n-1)]+=d[c][0]
for t in range(n-1):
    for u in cust:
        for v in cust:
            if u!=v: add(idx(u,t),idx(v,t+1),d[u][v])
spec={"type":"qubo","quadratic":[[i,j,round(v,6)] for (i,j),v in Q.items()],"linear":[round(v,6) for v in lin]}
json.dump(spec,open("problem.json","w")); print("P",P,"vars",n*n,"quad",len(Q))
EOF
python3 build.py
